def process_payment(idempotency_key,amount):
    key="idemp:"+idempotency_key
    if not redis.set(key,"pending",nx=True,ex=120):
        return redis.get(key)
    response=stripe.Charge.create(amount=amount)
    redis.set(key,response,ex=120)
    return response
